os.makedirs("data", exist_ok=True)
rows = [(t, "scam") for t in SCAM] + [(t, "legit") for t in LEGIT] + [(t, "uncertain") for t in UNSURE]
with open("data/prototype_demo.csv", "w", newline="", encoding="utf-8") as f:
    w = csv.writer(f); w.writerow(["id", "text", "label", "source"])
    for i, (t, l) in enumerate(rows, 1):
        w.writerow([i, t, l, "prototype_handwritten"])
print(len(SCAM), len(LEGIT), len(UNSURE), "->", len(rows), "rows in data/prototype_demo.csv")
